<?php
namespace App\Services;use App\Models\{Survey,ValidationRun};use Illuminate\Validation\ValidationException;
class ScientificValidationService{public function validate(Survey $survey,int $userId,float $holdoutPercent=20,float $power=2):ValidationRun{$rows=$survey->points()->where('validation_status','valid')->with(['measurements'=>fn($q)=>$q->where('is_simulated',false)->whereNotNull('rssi_dbm')->latest('captured_at')])->get();$points=[];foreach($rows as$p){$m=$p->measurements->first();if($m)$points[]=['id'=>$m->id,'x'=>(float)$p->x_normalized,'y'=>(float)$p->y_normalized,'observed'=>(float)$m->rssi_dbm];}if(count($points)<10)throw ValidationException::withMessages(['validation'=>'At least 10 valid non-simulated RSSI points are required.']);usort($points,fn($a,$b)=>$a['id']<=>$b['id']);$holdoutCount=max(2,(int)round(count($points)*($holdoutPercent/100)));$holdout=[];$training=[];$step=max(2,(int)floor(count($points)/$holdoutCount));foreach($points as$i=>$p){if(count($holdout)<$holdoutCount&&$i%$step===0)$holdout[]=$p;else$training[]=$p;}if(count($training)<3)throw ValidationException::withMessages(['validation'=>'At least three training points must remain after holdout selection.']);$predictions=[];$errors=[];foreach($holdout as$p){$predicted=$this->estimate($p['x'],$p['y'],$training,$power);$error=$predicted-$p['observed'];$errors[]=$error;$predictions[]=['measurement_id'=>$p['id'],'observed_rssi_dbm'=>$p['observed'],'predicted_rssi_dbm'=>round($predicted,4),'error_db'=>round($error,4),'absolute_error_db'=>round(abs($error),4)];}$mae=array_sum(array_map('abs',$errors))/count($errors);$rmse=sqrt(array_sum(array_map(fn($e)=>$e*$e,$errors))/count($errors));$bias=array_sum($errors)/count($errors);$max=max(array_map('abs',$errors));return ValidationRun::create(['survey_id'=>$survey->id,'executed_by'=>$userId,'method'=>'idw_holdout','algorithm_version'=>'1.0','status'=>'completed','total_points'=>count($points),'training_points'=>count($training),'holdout_points'=>count($holdout),'holdout_percent'=>round((count($holdout)/count($points))*100,3),'mean_absolute_error'=>round($mae,4),'root_mean_square_error'=>round($rmse,4),'mean_bias_error'=>round($bias,4),'maximum_absolute_error'=>round($max,4),'parameters'=>['power'=>$power,'selection'=>'deterministic_systematic_holdout'],'predictions'=>$predictions,'limitations'=>['Validation accuracy depends on measurement density, device consistency and environmental stability.'],'executed_at'=>now()]);}private function estimate(float$x,float$y,array$training,float$power):float{$sum=0;$weights=0;foreach($training as$p){$d=sqrt((($x-$p['x'])**2)+(($y-$p['y'])**2));if($d<0.000001)return$p['observed'];$w=1/($d**$power);$sum+=$w*$p['observed'];$weights+=$w;}return$sum/$weights;}}
